package com.college.guide;
import com.sun.net.httpserver.*; import java.io.*; import java.net.*; import java.nio.charset.StandardCharsets; import java.util.*;

public class App {
 static final Map<String,Session> sessions=new HashMap<>(); record Session(int id,String name,String role){}
 public static void main(String[] a)throws Exception { Database.initialize(); HttpServer s=HttpServer.create(new InetSocketAddress(8080),0); s.createContext("/",App::handle); s.setExecutor(null); s.start(); System.out.println("Guide Allocation System: http://localhost:8080"); }
 static void handle(HttpExchange x)throws IOException { try { String p=x.getRequestURI().getPath(); if(p.equals("/")||p.equals("/index.html")){send(x,200,"text/html",page());return;} if(p.equals("/app.js")){send(x,200,"application/javascript",js());return;} if(p.startsWith("/api/")){api(x,p);return;} send(x,404,"text/plain","Not found"); }catch(Exception e){boolean unauthenticated="Please log in".equals(e.getMessage()); if(!unauthenticated)e.printStackTrace(); send(x,unauthenticated?401:500,"application/json","{\"error\":\""+esc(e.getMessage())+"\"}");} }
 static void api(HttpExchange x,String p)throws Exception { MongoApi.handle(x,p); }
 static Map<String,String> form(HttpExchange x)throws IOException{Map<String,String>m=new HashMap<>();String z=new String(x.getRequestBody().readAllBytes(),StandardCharsets.UTF_8);for(String e:z.split("&")){String[]a=e.split("=",2);if(a.length==2)m.put(URLDecoder.decode(a[0],"UTF-8"),URLDecoder.decode(a[1],"UTF-8"));}return m;}
 static String cookie(HttpExchange x){String c=x.getRequestHeaders().getFirst("Cookie");return c==null?"":Arrays.stream(c.split("; *")).filter(v->v.startsWith("sid=")).map(v->v.substring(4)).findFirst().orElse("");} static Session session(HttpExchange x){return sessions.get(cookie(x));} static String esc(String s){return s==null?"":s.replace("\\","\\\\").replace("\"","\\\"").replace("\n"," ");} static void json(HttpExchange x,String s)throws IOException{send(x,200,"application/json",s);} static void send(HttpExchange x,int c,String t,String s)throws IOException{byte[]d=s.getBytes(StandardCharsets.UTF_8);x.getResponseHeaders().set("Content-Type",t+"; charset=utf-8");x.sendResponseHeaders(c,d.length);x.getResponseBody().write(d);x.close();}
 static String page(){return """
<!doctype html><html><head><meta name='viewport' content='width=device-width,initial-scale=1'><title>GuideFlow</title><style>
*{box-sizing:border-box}body{margin:0;background:#f4f7fb;color:#172033;font:15px Arial}header{background:#192b50;color:white;padding:18px 8%;display:flex;justify-content:space-between}main{max-width:1050px;margin:28px auto;padding:0 18px}.card{background:#fff;border-radius:10px;padding:20px;margin:14px 0;box-shadow:0 2px 12px #1d2d4d16}input,select,textarea,button{padding:10px;margin:5px;border:1px solid #ccd4e0;border-radius:6px}button{background:#2463b5;color:#fff;border:0;cursor:pointer}button.danger{background:#b53131}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:12px}.item{border-left:4px solid #346fbd;padding:10px;background:#fafcff}.tag{font-size:12px;background:#e2edff;padding:4px 8px;border-radius:20px}h1,h2,h3{margin-top:0}.muted{color:#64748b}#toast{position:fixed;bottom:20px;right:20px;background:#172033;color:white;padding:12px;border-radius:6px;display:none}</style></head><body><header><b>GuideFlow</b><span id='user'></span></header><main id='app'></main><div id='toast'></div><script src='/app.js'></script></body></html>""";}
 static String js(){return """
const app=document.querySelector('#app'), user=document.querySelector('#user');
const api=async(p,d)=>{let r=await fetch(p,{method:d?'POST':'GET',headers:d?{'Content-Type':'application/x-www-form-urlencoded'}:{},body:d?new URLSearchParams(d):undefined});let x=await r.json();if(!r.ok)throw Error(x.error);return x};
const note=x=>{let n=document.querySelector('#toast');n.textContent=x;n.style.display='block';setTimeout(()=>n.style.display='none',2500)};
const esc=x=>String(x??'').replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c])); const cards=(a,f)=>a.length?a.map(f).join(''):'<p class=muted>No records yet.</p>';
async function login(){app.innerHTML=`<section class='card' style='max-width:430px;margin:70px auto'><h1>Welcome to GuideFlow</h1><p class=muted>Faculty guide allocation and project management.</p><form id=l><input required name=email type=email placeholder='Email' style='width:100%'><input required name=password type=password placeholder='Password' style='width:100%'><button style='width:100%'>Sign in</button></form><p class=muted>Demo password for all accounts: password</p></section>`;l.onsubmit=async e=>{e.preventDefault();try{await api('/api/login',Object.fromEntries(new FormData(l)));home()}catch(x){note(x.message)}}}
async function home(){let me=await api('/api/me');user.innerHTML=`${esc(me.name)} · ${me.role} <button id=out>Logout</button>`;out.onclick=async()=>{await api('/api/logout',{});login()};if(me.role==='STUDENT')student();else if(me.role==='FACULTY')faculty();else admin()}
async function student(){let [fs,ds,rs,ps,as]=await Promise.all([api('/api/faculty'),api('/api/domains'),api('/api/my-requests'),api('/api/projects'),api('/api/announcements')]);app.innerHTML=`<h1>Student dashboard</h1><div class=grid><section class=card><h2>Request a guide</h2><form id=req><select name=facultyId>${fs.filter(f=>f.seats_left>0).map(f=>`<option value=${f.id}>${esc(f.name)} (${f.seats_left} seats)</option>`)}</select><select name=domainId>${ds.map(d=>`<option value=${d.id}>${esc(d.name)}</option>`)}</select><button>Submit request</button></form></section><section class=card><h2>Submit milestone</h2><form id=mil><input name=title required placeholder='Milestone title'><button>Submit</button></form></section></div><section class=card><h2>Available faculty</h2><div class=grid>${cards(fs,f=>`<div class=item><b>${esc(f.name)}</b><br>${esc(f.department)} · <span class=tag>${f.seats_left} seats left</span><p>${esc(f.domains)}</p></div>`)}</div></section><section class=card><h2>My requests</h2>${cards(rs,r=>`<div class=item>${esc(r.faculty)} — ${esc(r.domain)} <b>${r.status}</b></div>`)}</section><section class=card><h2>My project</h2>${cards(ps,p=>`<div class=item><b>${esc(p.title)}</b> · ${p.status}<br>${esc(p.faculty)} / ${esc(p.domain)}</div>`)}</section>${ann(as)}`;req.onsubmit=post('/api/request',req,student);mil.onsubmit=post('/api/milestone',mil,student)}
async function faculty(){let [r,p,a]=await Promise.all([api('/api/incoming'),api('/api/projects'),api('/api/announcements')]);app.innerHTML=`<h1>Faculty dashboard</h1><section class=card><h2>Incoming guide requests</h2>${cards(r,x=>`<div class=item><b>${esc(x.student)}</b> (${esc(x.registration_no)}) · ${esc(x.domain)} · <b>${x.status}</b>${x.status==='PENDING'?` <button onclick="decision(${x.id},'ACCEPTED')">Accept</button><button class=danger onclick="decision(${x.id},'REJECTED')">Reject</button>`:''}</div>`)}</section><section class=card><h2>Supervised projects</h2>${cards(p,x=>`<div class=item><b>${esc(x.title)}</b> — ${esc(x.student)} · ${x.status}</div>`)}</section><section class=card><h2>Post announcement</h2><form id=post><input name=title required placeholder=Title><textarea name=body required placeholder=Message></textarea><button>Post</button></form></section>${ann(a)}`;post.onsubmit=post('/api/announcement',post,faculty)}
async function admin(){let [rep,fs,ds,a]=await Promise.all([api('/api/report'),api('/api/faculty'),api('/api/domains'),api('/api/announcements')]);app.innerHTML=`<h1>Coordinator dashboard</h1><div class=grid><section class=card><h2>Add user</h2><form id=add><input name=name required placeholder=Name><input name=email required type=email placeholder=Email><input name=password required placeholder='Temporary password'><select name=role><option>STUDENT</option><option>FACULTY</option></select><input name=department required placeholder=Department><input name=registration placeholder='Registration no. (student)'><input name=semester type=number value=1 placeholder='Semester'><input name=capacity type=number value=5 placeholder='Capacity'><button>Create user</button></form></section><section class=card><h2>Assign faculty domain</h2><form id=assign><select name=facultyId>${fs.map(x=>`<option value=${x.id}>${esc(x.name)}</option>`)}</select><select name=domainId>${ds.map(x=>`<option value=${x.id}>${esc(x.name)}</option>`)}</select><button>Assign</button></form><h2>Allocation lock</h2><button id=lock>Lock new requests</button><button id=unlock>Unlock requests</button></section></div><section class=card><h2>Allocation report</h2>${cards(rep,x=>`<div class=item><b>${esc(x.faculty)}</b> — ${x.allocated_students} allocated student(s)</div>`)}</section><section class=card><h2>Faculty capacity</h2>${cards(fs,x=>`<div class=item><b>${esc(x.name)}</b> — ${x.current_students}/${x.max_students} allocated</div>`)}</section><section class=card><h2>Post announcement</h2><form id=post><input name=title required placeholder=Title><textarea name=body required placeholder=Message></textarea><button>Post</button></form></section>${ann(a)}`;post.onsubmit=post('/api/announcement',post,admin);add.onsubmit=post('/api/admin/user',add,admin);assign.onsubmit=post('/api/admin/domain',assign,admin);lock.onclick=()=>api('/api/admin/lock',{locked:'true'}).then(x=>{note(x.message);admin()});unlock.onclick=()=>api('/api/admin/lock',{locked:'false'}).then(x=>{note(x.message);admin()})}
function ann(a){return `<section class=card><h2>Announcements</h2>${cards(a,x=>`<div class=item><b>${esc(x.title)}</b><p>${esc(x.body)}</p><small>${esc(x.author)} · ${esc(x.created_at)}</small></div>`)}</section>`};function post(url,f,next){return async e=>{e.preventDefault();try{let x=await api(url,Object.fromEntries(new FormData(f)));note(x.message);next()}catch(x){note(x.message)}}};window.decision=async(id,status)=>{try{note((await api('/api/decision',{requestId:id,status})).message);faculty()}catch(x){note(x.message)}};home().catch(login);
""";}
}
